DIF = 0.001

dayly_bars = recon.get_all_frames("BTCUSDT").get("d")

def ext_search(bars):
    high_exts = []
    low_exts = []
    exts = []
    for bar in range(1, len(bars) -1):
        if bars[bar-1].get("high") < bars[bar].get("high") > bars[bar+1].get("high"):
            high_exts.append(bars[bar])
        if bars[bar-1].get("low") > bars[bar].get("low") < bars[bar+1].get("low"):
            low_exts.append(bars[bar])

    exts.append(low_exts)
    exts.append(high_exts)
    return exts


def get_level(exts):
    #1 low exts
    low_levels = []
    high_levels = []
    lcount = 0
    costs = []
    for bar in exts[0]:
        for nbar in exts[0]:
            if nbar.get("low") - DIF < bar.get("low") < nbar.get("low") + DIF:
                lcount += 1
                costs.append(nbar.get("low"))
        if lcount >= 3:
            low_levels.append(round(sum(costs)/len(costs), 2))
        lcount = 0
        costs = []
    #2 high exts

    for bar in exts[1]:
        for nbar in exts[1]:
            if nbar.get("high") - DIF < bar.get("high") < nbar.get("high") + DIF:
                lcount += 1
                costs.append(nbar.get("high"))
        if lcount >= 3:
            high_levels.append(round(sum(costs)/len(costs), 2))
        lcount = 0
        costs = []

    return [set(low_levels), set(high_levels)]